sealed class Block(int first, int last, List<string> labels) {
    public int First = first, Last = last;
    public List<string> Labels = labels;
    public List<int> Successors = new(), Predecessors = new();
}
sealed class NaturalLoop(int header, List<int> latches, HashSet<int> blocks, HashSet<int> exits, HashSet<int> outside) {
    public int Header = header, Depth;
    public List<int> Latches = latches;
    public HashSet<int> Blocks = blocks, Exits = exits, Outside = outside;
}
sealed class Graph {
    public List<Instruction> Instructions;
    public List<Block> Blocks = new();
    public int[] Owners;
    public List<int> Positions = new();
    public HashSet<int> Reachable = new();
    public List<int> Postorder = new(), Order;
    public List<HashSet<int>> Dominators;
    public int?[] Idom;
    public List<NaturalLoop> Loops = new();
    public int[] Depths;
    public Graph(Function function) {
        Instructions = function.Instructions;
        Owners = new int[Instructions.Count];
        Dictionary<int, List<string>> labels = new();
        HashSet<int> leaders = new() {
            0
        };
        int index = 0;
        for (int lineIndex = 0; lineIndex < function.Code.Count; lineIndex++) {
            if (function.Code[lineIndex] is LabelLine label) {
                if (!labels.ContainsKey(index)) labels[index] = new();
                labels[index].Add(label.Name);
                leaders.Add(index);
            }
            else {
                Instruction instruction = ((InstructionLine)function.Code[lineIndex]).Instruction;
                Positions.Add(lineIndex);
                index++;
                if (instruction.Kind is "goto" or "if" or "return" && index < Instructions.Count) leaders.Add(index);
            }
        }
        List<int> starts = leaders.OrderBy(value => value).ToList();
        for (int i = 0; i < starts.Count; i++) {
            int first = starts[i], last = i + 1 < starts.Count ? starts[i + 1] - 1 : Instructions.Count - 1;
            Blocks.Add(new(first, last, labels.GetValueOrDefault(first) ?? new()));
            for (int j = first; j <= last; j++) Owners[j] = i;
        }
        Dictionary<string, int> labelBlocks = new(StringComparer.Ordinal);
        for (int i = 0; i < Blocks.Count; i++) foreach (string label in Blocks[i].Labels) labelBlocks[label] = i;
        for (int i = 0; i < Blocks.Count; i++) {
            Block block = Blocks[i];
            Instruction instruction = Instructions[block.Last];
            if (instruction.Kind == "goto") block.Successors.Add(labelBlocks[instruction.Target]);
            else if (instruction.Kind == "if") {
                block.Successors.Add(i + 1);
                int target = labelBlocks[instruction.Target];
                if (target != i + 1) block.Successors.Add(target);
            } else if (instruction.Kind != "return") block.Successors.Add(i + 1);
        }
        for (int i = 0; i < Blocks.Count; i++) foreach (int j in Blocks[i].Successors) Blocks[j].Predecessors.Add(i);
        Visit(0);
        Order = Postorder.AsEnumerable().Reverse().ToList();
        Dominators = Enumerable.Range(0, Blocks.Count).Select(b => b == 0 ? new HashSet<int> {
            0
        } : new(Reachable)).ToList();
        Idom = new int?[Blocks.Count];
        while (true) {
            bool changed = false;
            foreach (int b in Order.Skip(1)) {
                HashSet<int> set = new(Reachable);
                foreach (int p in Blocks[b].Predecessors.Where(p => Reachable.Contains(p))) set.IntersectWith(Dominators[p]);
                set.Add(b);
                if (!set.SetEquals(Dominators[b])) {
                    Dominators[b] = set;
                    changed = true;
                }
            } if (!changed) break;
        }
        foreach (int b in Order.Skip(1)) Idom[b] = Dominators[b].Where(d => d != b).OrderByDescending(d => Dominators[d].Count).ThenBy(d => d).First();
        foreach (int h in Reachable.OrderBy(value => value)) {
            List<int> latches = Reachable.Where(t => Blocks[t].Successors.Contains(h) && Dominators[t].Contains(h)).OrderBy(t => t).ToList();
            if (latches.Count == 0) continue;
            HashSet<int> members = new() {
                h
            };
            Stack<int> pending = new(latches);
            while (pending.Count > 0) {
                int b = pending.Pop();
                if (b == h || !members.Add(b)) continue;
                foreach (int predecessor in Blocks[b].Predecessors.Where(p => Reachable.Contains(p))) pending.Push(predecessor);
            }
            HashSet<int> exits = new(), outside = new();
            foreach (int b in members) {
                if (Instructions[Blocks[b].Last].Kind == "return") exits.Add(b);
                foreach (int s in Blocks[b].Successors) {
                    if (!members.Contains(s)) {
                        exits.Add(b);
                        outside.Add(s);
                    }
                }
            } Loops.Add(new(h, latches, members, exits, outside));
        }
        Depths = Enumerable.Range(0, Blocks.Count).Select(b => Loops.Count(loop => loop.Blocks.Contains(b))).ToArray();
        foreach (NaturalLoop loop in Loops) loop.Depth = Loops.Count(candidate => candidate.Blocks.Contains(loop.Header));
    }
    void Visit(int b) {
        Reachable.Add(b);
        foreach (int s in Blocks[b].Successors) {
            if (!Reachable.Contains(s)) Visit(s);
        } Postorder.Add(b);
    }
}

readonly record struct DefinitionKey(string Variable, int Number);
readonly record struct CopyKey(string Destination, string Source);
sealed class FlowSets<T>(int count, HashSet<T>? initial = null) where T : notnull {
    public List<HashSet<T>> Input = Enumerable.Range(0, count).Select(_ => new HashSet<T>()).ToList();
    public List<HashSet<T>> Output = Enumerable.Range(0, count).Select(_ => initial == null ? new HashSet<T>() : new(initial)).ToList();
    public int Iterations;
}
static class Transfer {
    public static HashSet<DefinitionKey> Definitions(HashSet<DefinitionKey> original, Instruction instruction, int number) {
        HashSet<DefinitionKey> set = new(original);
        if (instruction.Destination is string x) {
            set.RemoveWhere(d => d.Variable == x);
            set.Add(new(x, number));
        } return set;
    }
    public static HashSet<string> Live(HashSet<string> original, Instruction instruction) {
        HashSet<string> set = new(original, StringComparer.Ordinal);
        if (instruction.Destination != null) set.Remove(instruction.Destination);
        set.UnionWith(instruction.Used);
        return set;
    }
    public static HashSet<TacExpression> Expressions(HashSet<TacExpression> original, Instruction instruction) {
        HashSet<TacExpression> set = new(original);
        if (instruction.Expression is TacExpression expression) set.Add(expression);
        if (instruction.Kind == "store") set.RemoveWhere(e => e.Kind == "load" && e.Operation == instruction.Array);
        if (instruction.Kind == "call") set.RemoveWhere(e => e.Kind == "load");
        if (instruction.Destination is string x) set.RemoveWhere(e => e.Uses(x));
        return set;
    }
    public static HashSet<CopyKey> Copies(HashSet<CopyKey> original, Instruction instruction) {
        HashSet<CopyKey> set = new(original);
        if (instruction.Destination is string x) {
            set.RemoveWhere(c => c.Destination == x || c.Source == x);
            if (instruction.Kind == "copy" && instruction.A?.Variable is string y && x != y) set.Add(new(x, y));
        } return set;
    }
}
sealed class Analysis {
    public FlowSets<DefinitionKey> Definitions;
    public FlowSets<string> Live;
    public FlowSets<TacExpression> Expressions;
    public FlowSets<CopyKey> Copies;
    public List<HashSet<DefinitionKey>> BeforeDefinitions;
    public List<HashSet<TacExpression>> BeforeExpressions;
    public List<HashSet<CopyKey>> BeforeCopies;
    public List<HashSet<string>> BeforeLive, AfterLive;
    public Analysis(Function function, Graph graph) {
        int count = graph.Blocks.Count, n = graph.Instructions.Count;
        List<int> reachable = Enumerable.Range(0, n).Where(i => graph.Reachable.Contains(graph.Owners[i])).ToList();
        HashSet<TacExpression> universe = reachable.Select(i => graph.Instructions[i].Expression).OfType<TacExpression>().ToHashSet();
        HashSet<CopyKey> copyUniverse = new();
        foreach (int i in reachable) {
            Instruction instruction = graph.Instructions[i];
            if (instruction.Kind == "copy" && instruction.Destination is string x && instruction.A?.Variable is string y && x != y) copyUniverse.Add(new(x, y));
        }
        Definitions = new(count);
        Live = new(count);
        Expressions = new(count, universe);
        Copies = new(count, copyUniverse);
        BeforeDefinitions = Enumerable.Range(0, n).Select(_ => new HashSet<DefinitionKey>()).ToList();
        BeforeExpressions = Enumerable.Range(0, n).Select(_ => new HashSet<TacExpression>()).ToList();
        BeforeCopies = Enumerable.Range(0, n).Select(_ => new HashSet<CopyKey>()).ToList();
        BeforeLive = Enumerable.Range(0, n).Select(_ => new HashSet<string>()).ToList();
        AfterLive = Enumerable.Range(0, n).Select(_ => new HashSet<string>()).ToList();
        while (true) {
            Definitions.Iterations++;
            bool changed = false;
            foreach (int b in graph.Order) {
                HashSet<DefinitionKey> set = b == 0 ? function.Parameters.Select(p => new DefinitionKey(p, 0)).ToHashSet() : new();
                foreach (int p in graph.Blocks[b].Predecessors.Where(p => graph.Reachable.Contains(p))) set.UnionWith(Definitions.Output[p]);
                Definitions.Input[b] = new(set);
                for (int i = graph.Blocks[b].First; i <= graph.Blocks[b].Last; i++) set = Transfer.Definitions(set, graph.Instructions[i], i + 1);
                if (!set.SetEquals(Definitions.Output[b])) changed = true;
                Definitions.Output[b] = set;
            }
            if (!changed) break;
        }
        while (true) {
            Live.Iterations++;
            bool changed = false;
            foreach (int b in graph.Postorder) {
                HashSet<string> set = graph.Blocks[b].Successors.SelectMany(s => Live.Input[s]).ToHashSet(StringComparer.Ordinal);
                Live.Output[b] = new(set, StringComparer.Ordinal);
                for (int i = graph.Blocks[b].Last; i >= graph.Blocks[b].First; i--) set = Transfer.Live(set, graph.Instructions[i]);
                if (!set.SetEquals(Live.Input[b])) changed = true;
                Live.Input[b] = set;
            }
            if (!changed) break;
        }
        Available(Expressions, graph, universe, Transfer.Expressions);
        Available(Copies, graph, copyUniverse, Transfer.Copies);
        foreach (int b in graph.Reachable) {
            HashSet<DefinitionKey> d = Definitions.Input[b];
            HashSet<TacExpression> e = Expressions.Input[b];
            HashSet<CopyKey> c = Copies.Input[b];
            for (int i = graph.Blocks[b].First; i <= graph.Blocks[b].Last; i++) {
                BeforeDefinitions[i] = new(d);
                BeforeExpressions[i] = new(e);
                BeforeCopies[i] = new(c);
                d = Transfer.Definitions(d, graph.Instructions[i], i + 1);
                e = Transfer.Expressions(e, graph.Instructions[i]);
                c = Transfer.Copies(c, graph.Instructions[i]);
            } HashSet<string> l = Live.Output[b];
            for (int i = graph.Blocks[b].Last; i >= graph.Blocks[b].First; i--) {
                AfterLive[i] = new(l, StringComparer.Ordinal);
                l = Transfer.Live(l, graph.Instructions[i]);
                BeforeLive[i] = new(l, StringComparer.Ordinal);
            }
        }
    }
    static void Available<T>(FlowSets<T> result, Graph graph, HashSet<T> universe, Func<HashSet<T>, Instruction, HashSet<T>> transfer) where T : notnull {
        while (true) {
            result.Iterations++;
            bool changed = false;
            foreach (int b in graph.Order) {
                HashSet<T> set = b == 0 ? new() : new(universe);
                if (b != 0) foreach (int p in graph.Blocks[b].Predecessors.Where(p => graph.Reachable.Contains(p))) set.IntersectWith(result.Output[p]);
                result.Input[b] = new(set);
                for (int i = graph.Blocks[b].First; i <= graph.Blocks[b].Last; i++) set = transfer(set, graph.Instructions[i]);
                if (!set.SetEquals(result.Output[b])) changed = true;
                result.Output[b] = set;
            } if (!changed) return;
        }
    }
}

sealed record FoldResult(bool Changed, Instruction? Instruction = null);
static class Optimizations {
    public static FoldResult Fold(Instruction instruction) {
        if (instruction.Kind is not ("bin" or "if")) return new(false);
        Operand a = instruction.A!, b = instruction.B!;
        long? x = a.Constant, y = b.Constant;
        if (x.HasValue && y.HasValue) {
            if (instruction.Operation is "/" or "%" && y.Value == 0) return new(false);
            long value = TacParser.Operation(instruction.Operation, x.Value, y.Value);
            if (instruction.Kind == "if") return value == 0 ? new(true) : new(true, new Instruction("goto") {
                Target = instruction.Target
            });
            return value >= int.MinValue && value <= int.MaxValue ? new(true, Instruction.Move(instruction.Destination!, new ConstantOperand(value))) : new(false);
        }
        if (instruction.Kind != "bin") return new(false);
        Operand? operand = instruction.Operation == "+" && x == 0 ? b : instruction.Operation is "+" or "-" && y == 0 ? a : instruction.Operation == "*" && x == 1 ? b : instruction.Operation is "*" or "/" && y == 1 ? a : instruction.Operation == "*" && (x == 0 || y == 0) ? new ConstantOperand(0) : null;
        return operand == null ? new(false) : new(true, Instruction.Move(instruction.Destination!, operand));
    }
    public static void Rewrite(Function function, Dictionary<int, List<Instruction>> replacements) {
        List<CodeLine> code = new();
        int number = 0;
        foreach (CodeLine line in function.Code) {
            if (line is LabelLine) code.Add(line);
            else {
                if (replacements.TryGetValue(number++, out List<Instruction>? replacement)) code.AddRange(replacement.Select(instruction => new InstructionLine(instruction)));
                else code.Add(line);
            }
        } function.Code = code;
    }
    public static string Temporary(Function function) => "_t" + ++function.Temporary;
    public static List<Instruction> CseRewrite(Instruction instruction, string temporary, bool source) {
        Instruction copy = Instruction.Move(instruction.Destination!, new VariableOperand(temporary));
        return source ? new() {
            instruction with {
                Destination = temporary
            }, copy
        } : new() {
            copy
        };
    }
    public static string Hoist(Function function, Graph graph, NaturalLoop loop, List<int> moved) {
        int h = loop.Header;
        List<int> outside = graph.Blocks[h].Predecessors.Where(p => !loop.Blocks.Contains(p)).ToList();
        int? preheader = h != 0 && outside.Count == 1 && graph.Blocks[outside[0]].Successors.SequenceEqual(new[] {
            h
        }) ? outside[0] : null;
        HashSet<int> moving = moved.ToHashSet();
        List<Instruction> instructions = graph.Instructions;
        List<CodeLine> insertion = new(), before = function.Code.ToList();
        int position;
        string target;
        if (preheader.HasValue) {
            int last = graph.Blocks[preheader.Value].Last;
            position = graph.Positions[last] + (instructions[last].Kind is "goto" or "if" ? 0 : 1);
            target = $"B{preheader.Value + 1}";
        }
        else {
            string label = "_p" + ++function.Preheader;
            target = "new " + label;
            insertion.Add(new LabelLine(label));
            int first = graph.Positions[graph.Blocks[h].First];
            while (first > 0 && function.Code[first - 1] is LabelLine) first--;
            position = first;
            foreach (int p in outside) {
                int index = graph.Blocks[p].Last;
                if (instructions[index].Kind is "goto" or "if" && graph.Blocks[h].Labels.Contains(instructions[index].Target)) before[graph.Positions[index]] = new InstructionLine(instructions[index] with {
                    Target = label
                });
            }
        }
        insertion.AddRange(moved.Select(i => new InstructionLine(instructions[i])));
        List<CodeLine> code = new();
        int number = 0;
        for (int i = 0; i < before.Count; i++) {
            if (i == position) code.AddRange(insertion);
            CodeLine line = before[i];
            if (line is LabelLine) code.Add(line);
            else {
                if (!moving.Contains(number)) code.Add(line);
                number++;
            }
        } if (position == before.Count) code.AddRange(insertion);
        function.Code = code;
        return target;
    }
    public static List<string> Unreachable(Function function, Graph graph) {
        List<string> records = Enumerable.Range(0, graph.Blocks.Count).Where(b => !graph.Reachable.Contains(b)).Select(b => $"remove block B{b + 1}").ToList();
        List<CodeLine> code = new(), labels = new();
        int number = 0;
        foreach (CodeLine line in function.Code) {
            if (line is LabelLine) labels.Add(line);
            else {
                if (graph.Reachable.Contains(graph.Owners[number])) {
                    code.AddRange(labels);
                    code.Add(line);
                } labels.Clear();
                number++;
            }
        }
        HashSet<int> deleted = new();
        number = 0;
        for (int i = 0; i < code.Count; i++) {
            if (code[i] is InstructionLine line) {
                number++;
                if (line.Instruction.Kind is "goto" or "if") {
                    int j = i + 1;
                    while (j < code.Count && code[j] is LabelLine label) {
                        if (label.Name == line.Instruction.Target) {
                            deleted.Add(i);
                            records.Add($"remove jump #{number}");
                            break;
                        } j++;
                    }
                }
            }
        }
        code = code.Where((line, i) => !deleted.Contains(i)).ToList();
        HashSet<string> targets = code.OfType<InstructionLine>().Where(line => line.Instruction.Kind is "goto" or "if").Select(line => line.Instruction.Target).ToHashSet(StringComparer.Ordinal);
        function.Code = code.Where(line => {
            if (line is LabelLine label && !targets.Contains(label.Name)) {
                records.Add("remove label " + label.Name);
                return false;
            } return true;
        }).ToList();
        return records;
    }
}

global using System;
global using System.IO;
global using System.Linq;
global using System.Collections.Generic;
global using System.Numerics;
using System.Globalization;
static class Program {
    public static readonly string[] PassNames = {
        "constprop", "copyprop", "cse", "dce", "licm", "unreachable"
    };
    public static readonly string[] Kinds = {
        "copy", "bin", "load", "store", "goto", "if", "param", "call", "return", "read", "print"
    };
    static string FormatList(IEnumerable<string> values) {
        List<string> items = values.ToList();
        return items.Count == 0 ? "-" : string.Join(",", items);
    }
    static string BlockList(IEnumerable<int> values) => FormatList(values.Select(value => $"B{value + 1}"));
    static string Numbers(IEnumerable<int> values) => FormatList(values.Select(value => $"#{value + 1}"));
    static long? Constant(List<Instruction> instructions, HashSet<DefinitionKey> definitions, string variable) {
        List<int> numbers = definitions.Where(d => d.Variable == variable).Select(d => d.Number).ToList();
        if (numbers.Count == 0 || numbers.Contains(0)) return null;
        long? value = null;
        foreach (int number in numbers) {
            Instruction instruction = instructions[number - 1];
            if (instruction.Kind != "copy" || !instruction.A!.Constant.HasValue) return null;
            long current = instruction.A.Constant.Value;
            if (value.HasValue && value.Value != current) return null;
            value = current;
        } return value;
    }
    static (int, List<string>) Propagate(Function function, Graph graph, Analysis analysis, bool constants) {
        List<Instruction> instructions = graph.Instructions;
        Dictionary<int, List<Instruction>> replacements = new();
        List<string> records = new();
        for (int i = 0; i < instructions.Count; i++) {
            if (!graph.Reachable.Contains(graph.Owners[i])) continue;
            Instruction instruction = instructions[i] with {
            };
            for (int field = 0; field < 2; field++) {
                Operand? operand = field == 0 ? instruction.A : instruction.B;
                if (operand?.Variable is not string variable) continue;
                Operand? replacement = null;
                if (constants) {
                    long? value = Constant(instructions, analysis.BeforeDefinitions[i], variable);
                    if (value.HasValue) replacement = new ConstantOperand(value.Value);
                }
                else {
                    foreach (CopyKey copy in analysis.BeforeCopies[i]) {
                        if (copy.Destination == variable) {
                            replacement = new VariableOperand(copy.Source);
                            break;
                        }
                    }
                }
                if (replacement != null) {
                    records.Add($"#{i + 1}: {variable} -> {replacement.Text}");
                    if (field == 0) instruction.A = replacement;
                    else instruction.B = replacement;
                }
            }
            if (constants) {
                FoldResult folded = Optimizations.Fold(instruction);
                if (folded.Changed) {
                    if (folded.Instruction == null) {
                        records.Add($"#{i + 1}: delete {instruction.Text}");
                        replacements[i] = new();
                    } else {
                        records.Add($"#{i + 1}: fold {folded.Instruction.Text}");
                        replacements[i] = new() {
                            folded.Instruction
                        };
                    } continue;
                }
            }
            replacements[i] = new() {
                instruction
            };
        }
        Optimizations.Rewrite(function, replacements);
        return (records.Count, records);
    }
    static (int, List<string>) Cse(Function function, Graph graph, Analysis analysis) {
        List<Instruction> instructions = graph.Instructions;
        Dictionary<TacExpression, List<int>> groups = new();
        for (int i = 0; i < instructions.Count; i++) {
            if (graph.Reachable.Contains(graph.Owners[i]) && instructions[i].Expression is TacExpression expression && analysis.BeforeExpressions[i].Contains(expression)) {
                if (!groups.ContainsKey(expression)) groups[expression] = new();
                groups[expression].Add(i);
            }
        }
        Dictionary<int, List<Instruction>> replacements = new();
        List<string> records = new();
        int count = 0;
        foreach (var (expression, candidates) in groups.OrderBy(group => group.Value[0])) {
            HashSet<int> sources = new();
            foreach (int candidate in candidates) {
                int block = graph.Owners[candidate], first = graph.Blocks[block].First;
                int? source = null;
                for (int i = candidate - 1; i >= first; i--) {
                    if (instructions[i].Expression == expression) {
                        source = i;
                        break;
                    }
                } if (source.HasValue) {
                    sources.Add(source.Value);
                    continue;
                }
                Stack<int> pending = new(graph.Blocks[block].Predecessors.Where(p => graph.Reachable.Contains(p)));
                HashSet<int> seen = new();
                while (pending.Count > 0) {
                    int current = pending.Pop();
                    if (!seen.Add(current)) continue;
                    int? found = null;
                    for (int i = graph.Blocks[current].Last; i >= graph.Blocks[current].First; i--) {
                        if (instructions[i].Expression == expression) {
                            found = i;
                            break;
                        }
                    } if (found.HasValue) sources.Add(found.Value);
                    else foreach (int p in graph.Blocks[current].Predecessors.Where(p => graph.Reachable.Contains(p))) pending.Push(p);
                }
            }
            sources.ExceptWith(candidates);
            string temporary = Optimizations.Temporary(function);
            foreach (int source in sources) replacements[source] = Optimizations.CseRewrite(instructions[source], temporary, true);
            foreach (int candidate in candidates) replacements[candidate] = Optimizations.CseRewrite(instructions[candidate], temporary, false);
            records.Add($"{expression.Text}: {temporary} sources={Numbers(sources.OrderBy(value => value))} replaced={Numbers(candidates)}");
            count += candidates.Count;
        }
        Optimizations.Rewrite(function, replacements);
        return (count, records);
    }
    static (int, List<string>) Dce(Function function, Graph graph, Analysis analysis) {
        Dictionary<int, List<Instruction>> replacements = new();
        Dictionary<int, string> records = new();
        foreach (int b in graph.Reachable.OrderBy(value => value)) {
            HashSet<string> live = analysis.Live.Output[b];
            for (int i = graph.Blocks[b].Last; i >= graph.Blocks[b].First; i--) {
                Instruction instruction = graph.Instructions[i] with {
                };
                bool selfCopy = instruction.Kind == "copy" && instruction.Destination == instruction.A?.Variable, dead = instruction.Kind is "copy" or "bin" or "load" && instruction.Destination != null && !live.Contains(instruction.Destination);
                if (selfCopy || dead) {
                    replacements[i] = new();
                    records[i] = $"#{i + 1}: delete {instruction.Text}";
                    continue;
                }
                if (instruction.Kind == "call" && instruction.Destination is string x && !live.Contains(x)) {
                    records[i] = $"#{i + 1}: unused result {instruction.Text}";
                    instruction.Destination = null;
                    replacements[i] = new() {
                        instruction
                    };
                } live = Transfer.Live(live, instruction);
            }
        }
        Optimizations.Rewrite(function, replacements);
        List<string> lines = records.OrderBy(pair => pair.Key).Select(pair => pair.Value).ToList();
        return (lines.Count, lines);
    }
    static (int, List<string>) Licm(Function function, Graph graph, Analysis analysis) {
        List<Instruction> instructions = graph.Instructions;
        foreach (NaturalLoop loop in graph.Loops.OrderBy(loop => loop.Blocks.Count).ThenBy(loop => loop.Header)) {
            bool Inside(int number) => number != 0 && loop.Blocks.Contains(graph.Owners[number - 1]);
            List<int> indices = Enumerable.Range(0, instructions.Count).Where(i => loop.Blocks.Contains(graph.Owners[i])).ToList();
            HashSet<int> marked = new();
            List<int> order = new();
            while (true) {
                bool changed = false;
                foreach (int i in indices) {
