    static HashSet<int> Reach(int start, List<List<int>> edges) {
        Stack<int> pending = new();
        pending.Push(start);
        HashSet<int> seen = new();
        while (pending.Count > 0) {
            int i = pending.Pop();
            if (seen.Add(i)) foreach (int j in edges[i]) pending.Push(j);
        } return seen;
    }
